// DDROID simulated pump / fill logic
// State machine stored in flow context "pump": "OFF" | "ON"
// Rules:
//   - Starts OFF (set in the On Start tab)
//   - Water LOW    -> pump ON  (start filling)
//   - Water FULL   -> pump OFF (stop filling)
//   - STOP command -> pump OFF (stop filling)

let pump = flow.get("pump");
if (pump === undefined) { pump = "OFF"; }

const topic = (msg.topic || "").toString().toLowerCase();
const value = (msg.payload || "").toString().toUpperCase();
let event = "no change";

if (topic === "command" && value === "STOP") {
    pump = "OFF";
    event = "STOP pressed -> pump OFF";
} else if (topic === "level" && value === "LOW") {
    pump = "ON";
    event = "Water LOW -> start filling";
} else if (topic === "level" && value === "FULL") {
    pump = "OFF";
    event = "Water FULL -> stop filling";
} else if (topic === "init") {
    pump = "OFF";
    event = "Initialised -> pump OFF";
}

flow.set("pump", pump);

node.status({
    fill: pump === "ON" ? "green" : "red",
    shape: "dot",
    text: "Pump " + pump
});

msg.payload = {
    pump: pump,
    filling: (pump === "ON"),
    event: event
};
return msg;
